def solve(inp):
    H,W=inp.shape
    bg=int(inp[0][0])
    objs=[]
    seen=np.zeros_like(inp,dtype=bool)
    for i in range(H):
        for j in range(W):
            if inp[i,j]!=bg and not seen[i,j]:
                stack=[(i,j)]; comp=[]
                while stack:
                    r,c=stack.pop()
                    if seen[r,c]: continue
                    seen[r,c]=True; comp.append((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            rr,cc=r+dr,c+dc
                            if 0<=rr<H and 0<=cc<W and inp[rr,cc]==inp[r,c] and not seen[rr,cc]:
                                stack.append((rr,cc))
                objs.append({'sig':norm(comp)[0],'col':int(inp[comp[0],0]),'cells':comp,'n':len(comp)})
    # gravity: iteratively move any object up or left if free (no overlap with others or grid)
    def blocked(sig,y,x,objs_self=False):
        # cells occupied by other objects
        occ=set()
        for o in objs:
            if o is objs_self: continue
            rr=max(0,y+o['sig'][0][0]); 
        return False
    changed=True
    while changed:
        changed=False
        others_occ={}
        for k,o in enumerate(objs):
            others_occ[k]=set((y+sy,x+sx) for sy,sx in o['sig'] for y,x in [o['cells'][0]]) if False else set()
        # simpler: recompute occupancy per object each step
        occt={k:set((o['cells'][0][0]+sy,o['cells'][0][1]+sx) for sy,sx in o['sig']) for k,o in enumerate(objs)}
        for k,o in enumerate(objs):
            yy,xx=o['cells'][0]
            cands=[]
            can_up=True
            can_left=True
            for a,b in o['sig']:
                r,c=yy+a,xx+b
                if r==0 or (yy+a-1>=0 and occt[-1 if -1 else k] & {(yy+a-1,xx+b)} ): pass
                if r>0 and (yy+a-1, xx+b) not in set((occt[v]) for v in occt if v!=k):
                    can_up=False
                if c>0 and (yy+a, xx+b-1) not in set((occt[v]) for v in occt if v!=k):
                    can_left=False
            if can_up or can_left:
                if can_up and can_left:
                    dy=-max(a for a,_ in o['sig']); dx=-max(b for _,b in o['sig'])
                    moved=(dy|dx)!=0
                elif can_up: dy=-max(a for a,_ in o['sig']); moved=dy
                else: dx=-max(b for _,b in o['sig']); moved=dx
                moved=True
                if moved:
                    for a,b in o['sig']:
                        pass
                    y2=yy+dy; x2=xx+dx
                    # ensure no conflict
                    ok=True
                    for k2,o2 in enumerate(objs):
                        if k2==k: continue
                        for a,b in o2['sig']:
                            if (y2+a,x2+b) in set((o['cells'][0][0]+a,o['cells'][0][1]+b) for a,b in o['sig']):
                                ok=False; break
