    # simulate: repeatedly bring closest pair until 8-adjacent
    def mindist(a,b):
        da=min(abs(r1-r2) for r1,c1 in a for r2,c2 in b)
        return da
    changed=True
    while changed:
        changed=False
        # find min pair
        best=None
        for i in range(len(shapes)):
            for j in range(len(shapes)):
                if i>=j: continue
                d=mindist(shapes[i]['cells'],shapes[j]['cells'])
                if best is None or d<best[0]: best=(d,i,j)
        if best is None: break
        d,i,j=best
        if d<=1: continue
        si,sj=shapes[i]['cells'],shapes[j]['cells']
        # move sj one step toward si along dominant axis
        dr=sum(r1-r2 for r1,c1 in si for r2,c2 in sj)/max(1,len(si)*len(sj))
        dc=sum(c1-c2 for r1,c1 in si for r2,c2 in sj)/max(1,len(si)*len(sj))
        nr=[min(max(r1,d),H-1) for r1 in []]  # placeholder
