        for nd,(nr_,nc_) in [((sj.r_[0]+1, sj.c_[0]-1),None)]: pass
        moved=False
        for step in [(1,0),(-1,0),(0,1),(0,-1)]:
            n={(r+step[0],c+step[1]) for r,c in sj}
            if all(0<=r<H and 0<=c<W for r,c in n) and not (n & si):
                moved=n;break
        if moved:
            shapes[i]['cells']=moved; changed=True
    # recolor singles to adjacent shape color, attach
    out=[[bg]*W for _ in range(H)]
    for o in shapes:
        for r,c in o['cells']: out[r][c]=o['col']
    for s in singles:
        r,c=list(s['cells'])[0]
        adj=[(I[r+a][c+b],a,b) for a in(-1,0,1) for b in(-1,0,1) if (a,b) and 0<=r+a<H and 0<=c+b<W and I[r+a][c+b]!=bg]
        if adj:
            col=max(adj,key=lambda t:t[0])
            out[r][c]=col
    return out,bg,objs

