def solve(I):
    H=len(I); W=len(I[0])
    bg=Counter(x for r in I for x in r).most_common(1)[0][0]
    seen=set(); objs=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]!=bg and (r,c) not in seen:
                col=I[r][c]; st=[(r,c)]; comp={(r,c)}; seen.add((r,c))
                while st:
                    a,b=st.pop()
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            n=(a+dr,b+dc)
                            if 0<=n[0]<H and 0<=n[1]<W and I[n[0]][n[1]]==col and n not in comp:
                                comp.add(n); st.append(n)
                objs.append((col,comp))
    singles=[o for o in objs if len(o[1])==1]; bigs=[o for o in objs if len(o[1])>1]
    att={}
    for s in singles:
        (pr,pc),=s[1]
        best=min(bigs,key=lambda b:min(max(abs(pr-q[0]),abs(pc-q[1])) for q in b[1]))
        att[(pr,pc)]=best
    occ=set(); items=[]
    for b in sorted(bigs,key=lambda b:-max(r for r,c in b[1])):
        col=b[0]
        cur=b[1]|set(p for p,v in att.items() if v==b)
        # translate relative so min row=0 within object for easier math
        def slide(cur):
            moved=cur
            while True:
                nxt={(r+1,c) for r,c in moved}
                if any(r>=H for r,c in nxt) or nxt&occ: break
                moved=nxt
            while True:
                nxt={(r,c-1) for r,c in moved}
                if any(c<0 for r,c in nxt) or nxt&occ: break
                moved=nxt
            return moved
        cur=slide(cur)
        items.append((cur,col)); occ|=cur
    mr=min(r for r,c in occ); mc=min(c for r,c in occ)
    Wd=max(c for r,c in occ)-mc+1
    out=[[bg]*Wd for _ in range(H)]
    for cur,col in items:
        for r,c in cur:
            out[r-mr][c-mc]=col
    return out

